output-exprs.el:
comment:index(
  ac!allComments,
  wherecontains(
    true,
    toboolean(
      property(ac!allComments, "isDraft", null)
    )
  ),
  null
)

previousComments:index(
  ac!allComments,
  wherecontains(
    false,
    toboolean(
      property(ac!allComments, "isDraft", null)
    )
  ),
  null
)

